#!/usr/bin/env bash
# DREAM Anatomy · batch 1: hero videos V1/V2 (1080p) + ten keyframes. Saves nodes only; run with jm.py run.
set -euo pipefail
cd "$(dirname "$0")/../.."
J="python3 tools/jm.py film02/jimeng-state.json"
LOCK="【产品身份锁定】画面中唯一的产品是参考图中的同一台 CoolFly Dream 单人电动飞行器：橙色整流罩，车头有两道白色竖条纹和「05」号码；深灰色钢管防滚架，座舱上方为拱形顶；白色座椅和安全带；四根碳纤维机臂呈 X 形向前后伸出，每根机臂末端上下各一组黑色电机和两叶碳纤维螺旋桨，共 8 副螺旋桨；机身底部为镂空钢管底盘。不增加或减少机臂、电机、螺旋桨，不改变比例和涂装，不出现第二台飞行器，不出现任何文字、字幕或水印。"
STUDIO="纯黑无缝影棚，低调摄影，高反差；真实材质：碳纤维编织纹理、整流罩喷漆的清漆高光、哑光钢管。冷静、精密、昂贵的高端产品广告质感，超写实，细节锐利。"
PILOT="座椅上坐着一名驾驶员：黑色连体飞行服、黑色手套、深色哑光全盔，烟色面罩完全遮住脸，看不到面部。"
MOVE="运镜：长缓入、稳定滑行、精准减速，有真实的重量感，禁止轻飘感、抖动和变焦跳变。"

$J vid V1 --title "V1 video · S3-4 亮相慢推" --first K1 --last K1z --dur 5 --prompt "$LOCK 全程一个连续镜头，从首帧画面平滑过渡到尾帧画面：镜头以 65mm 从略高位置缓慢推近，$MOVE 产品完全静止，螺旋桨不转，灯光保持不变，地面倒影稳定。结构、比例、涂装全程不变，不变形，不闪烁。"
$J vid V2 --title "V2 video · S7 电机启动" --first K3 --dur 4 --prompt "$LOCK 以首帧画面为起点，镜头锁定不动。0.0–1.0 秒静止；1.0–3.0 秒上下两组电机同时启动，螺旋桨从静止加速旋转，直至形成半透明的圆形虚影；3.0–4.0 秒保持高速旋转。绿色指示灯保持常亮；机臂和电机本体完全不动、不变形；空气轻微扰动。"

$J img K5 --title "K5 · S1 桨尖微距" --ref G-v6-low --ref K3 --prompt "生成一张 16:9 横屏超写实微距产品摄影画面。$LOCK 100mm 微距特写：一片碳纤维螺旋桨桨叶从画面左下斜向右上方伸出，桨尖位于画面中央偏右；正上方一束窄顶光只照亮桨叶上表面的碳纤维编织纹理和锐利的前缘，其余全部隐没在黑暗中；背景远处极暗、虚化的电机轮廓。$STUDIO"
$J img K6 --title "K6 · S5a 钢管焊点微距" --ref G-v1-front34 --ref K1 --prompt "生成一张 16:9 横屏超写实微距产品摄影画面。$LOCK 100mm 微距特写：深灰色哑光钢管防滚架的一个三向焊接节点，焊缝纹理细腻规整；一条侧逆光沿钢管弧面划出细长高光；背景是虚化的白色座椅边缘和黑暗。$STUDIO"
$J img K7 --title "K7 · S5b 碳纤维机臂纹理" --ref G-v6-low --ref K3 --prompt "生成一张 16:9 横屏超写实微距产品摄影画面。$LOCK 100mm 微距特写：碳纤维机臂的编织纹理占据画面，机臂上一个黑色金属卡箍和螺丝；光线斜向掠过，让编织纹理产生细腻的明暗变化；浅景深。$STUDIO"
$J img K8 --title "K8 · S5c 车头条纹微距" --ref G-v3-front --ref K1 --prompt "生成一张 16:9 横屏超写实微距产品摄影画面。$LOCK 85mm 特写：橙色整流罩车头，两道白色竖条纹从画面下方延伸到上方，清漆表面有一条柔和的长条反光；只拍整流罩局部，不出现号码和文字。$STUDIO"
$J img K9 --title "K9 · S6 沿机臂单点透视" --ref G-v4-top --ref G-v6-low --ref K3 --prompt "生成一张 16:9 横屏超写实产品摄影画面。$LOCK 极低机位，摄影机贴着一根碳纤维机臂的根部，沿机臂长度方向向外拍摄，形成强烈的单点透视：机臂从画面底部中央向远处延伸，末端是上下两组黑色电机和螺旋桨，位于画面中央的消失点附近，清晰对焦；近处机臂轻微虚化。顶光和两侧轮廓光勾出机臂边缘。$STUDIO"
$J img K10 --title "K10 · S11 水面影棚起飞前" --ref G-v1-front34 --ref K1 --prompt "生成一张 16:9 横屏超写实产品广告画面。$LOCK $PILOT 产品 3/4 前侧视角，停在纯黑影棚中一层极浅、如镜面般平静的积水上，水面清晰倒映出产品；顶光照亮机身，水面上有细长的高光。低机位，镜头接近水面。$STUDIO"
$J img K4b --title "K4b · S14 后方跟拍 崖顶起飞" --ref G-v5-rear34 --ref K1 --ref K4 --prompt "生成一张 16:9 横屏超写实电影摄影画面。$LOCK $PILOT 摄影机位于飞行器后上方约 3 米跟拍，能看到驾驶员的头盔和肩背、防滚架、四根机臂和螺旋桨；飞行器刚从海边悬崖顶的岩石平台升起约 2 米，前方是开阔的大海和礁石海岸线。清晨阴天的银灰色柔光，远处海平面有薄雾，低饱和、克制、高级。35mm 镜头。"
$J img K11 --title "K11 · S15 海岸航拍跟飞" --ref G-v2-side --ref K1 --ref K4 --prompt "生成一张 16:9 横屏超写实电影航拍画面。$LOCK $PILOT 飞行器侧面朝向镜头，在海边悬崖旁约 60 米高度平稳飞行，长焦镜头平行跟拍，飞行器占画面宽度约四分之一，位于左侧三分线；背景是层叠的礁石悬崖、白色浪花和远处的灯塔。清晨阴天银灰色柔光，低饱和、克制、高级，螺旋桨呈半透明旋转虚影。"
$J img K12 --title "K12 · S16 低空掠海" --ref G-v5-rear34 --ref K1 --prompt "生成一张 16:9 横屏超写实电影摄影画面。$LOCK $PILOT 摄影机从侧后方追拍，飞行器在离海面约 15 米的高度平稳飞行，下方是深蓝灰色的海面和细碎的白色浪花，远处是起伏的海岸线和薄雾。阴天柔光，低饱和、克制、高级，螺旋桨呈半透明旋转虚影。50mm 镜头。"
$J img K13 --title "K13 · S17 整流罩反光" --ref G-v3-front --ref K1 --prompt "生成一张 16:9 横屏超写实微距产品摄影画面。$LOCK 极近距离拍摄橙色整流罩的弧形表面，清漆表面倒映出阴天的天空和海平线，一道明亮的反光横穿画面中央；只拍整流罩表面，不出现号码和文字。电影感，浅景深。"
